import { StyleFn } from "..";

/**
 * common input reset and minimal styling
 */
export const BareInput: StyleFn = (theme, mode) => {
  const { color, font, opacity } = theme;

  return {
    root: {
      // reset default input appearance
      boxSizing: "border-box",
      margin: "0",
      width: "100%",
      border: "none",
      appearance: "none", // necessary for select
      fontFamily: "inherit",
      outline: "0",
      background: "transparent",
      // minimal styling
      fontSize: font.size.small,
      lineHeight: font.lineheight.small,
      color: color.text.neutral.default[mode],
      "&::placeholder": {
        color: color.text.neutral.strong[mode],
      },
      // FIXME breaks visual difference between empty and filled input on hover
      // "&:hover::placeholder": {
      //   color: color.text.neutral.default[mode],
      // },
      "&:disabled": {
        opacity: opacity.disabled,
        userSelect: "none",
        pointerEvents: "none",
      },
    },
  };
};

/**
 * common input look&feel and variants
 */
export const InputStyling: StyleFn = (theme, mode) => {
  const { color, font, opacity, size } = theme;

  const colorVariant = (color: string) => ({
    boxShadow: `0 3px 0 0 ${color}`,
    "&:focus, &:focus-within": { boxShadow: `0 0 0 3px ${color}` },
  });

  return {
    root: {
      height: size.spacing[40],
      padding: size.spacing[8],
      backgroundColor: color.surface.componentbackground.minimal[mode],
      borderRadius: "3px 3px 0 0",
      boxShadow: `0 1px 0 0 ${color.border.neutral.strong[mode]}`,
      transition: "0.1s ease-in-out",
      transitionProperty: "box-shadow, border",
      fontSize: font.size.small,
      "&:hover": {
        backgroundColor: color.surface.interaction.hover[mode],
      },
      // increased specificity to override [data-theme=dark] styles
      "&$_info&": colorVariant(color.border.feedback.information[mode]),
      "&$_valid&": colorVariant(color.border.feedback.success[mode]),
      "&$_invalid&": colorVariant(color.border.feedback.error[mode]),
    },
    _focused: {
      backgroundColor: color.surface.interaction.active[mode],
      borderColor: "transparent",
      boxShadow: `0 0 0 3px ${color.border.accent.focus[mode]}`,
    },
    _disabled: {
      opacity: opacity.disabled,
      pointerEvents: "none",
      // FIXME this cursor could be placed on form-control wrapper element
      // see https://stackoverflow.com/a/46665946/3641075
      // cursor: "not-allowed",
    },
    _info: {},
    _valid: {},
    _invalid: {},
    _readonly: {
      backgroundColor: "unset",
      boxShadow: `0 -1px 0 0 ${color.border.neutral.strong[mode]} inset`,
    },
    _xsmall: {
      paddingTop: size.spacing[2],
      paddingBottom: size.spacing[2],
      height: size.spacing[24],
      lineHeight: font.lineheight.xxsmall,
    },
    _small: {
      paddingTop: size.spacing[4],
      paddingBottom: size.spacing[4],
      height: size.spacing[32],
      lineHeight: font.lineheight.xsmall,
    },
    _medium: {},
    _large: {
      "& ": {
        height: size.spacing[48],
        fontSize: font.size.medium,
        lineHeight: font.lineheight.medium,
      },
    },
    _xlarge: {
      "& ": {
        height: size.spacing[56],
        fontSize: font.size.large,
        lineHeight: font.lineheight.xlarge,
      },
    },
  };
};

/**
 * Input component with adornments
 */
export const Input: StyleFn = (theme, mode) => {
  const { size } = theme;
  const { root: bareStyling } = BareInput(theme, mode);
  const {
    root: rootStyling,
    _focused,
    _disabled,
    _xsmall,
    _small,
    _large,
    _xlarge,
    _readonly,
    ...inputVariants
  } = InputStyling(theme, mode);

  return {
    root: {
      ...bareStyling,
      ...rootStyling,
      "&:disabled": _disabled,
      "&$root&:read-only": _readonly,
      "&:focus, &:focus-within": _focused,
      // support native input dialogs in dark mode
      colorScheme: mode,
    },
    group: {
      display: "flex",
      position: "relative",
    },
    _large: {
      ..._large,
      "&$_adornedStart": {
        paddingLeft: size.spacing[40],
      },
      "&$_adornedEnd": {
        paddingRight: size.spacing[56],
      },
    },
    _xlarge: {
      ..._xlarge,
      "&$_adornedStart": {
        paddingLeft: size.spacing[40],
      },
      "&$_adornedEnd": {
        paddingRight: size.spacing[56],
      },
    },
    _small: {
      ..._small,
      "&$_adornedStart": {
        paddingLeft: size.spacing[32],
      },
    },
    _xsmall: {
      ..._xsmall,
      "&$_adornedStart": {
        paddingLeft: size.spacing[32],
      },
      "&$_adornedEnd": {
        paddingRight: size.spacing[40],
      },
    },
    _adornedStart: {
      paddingLeft: `calc(${size.spacing[40]} - 4px)`,
    },
    _adornedEnd: {
      paddingRight: size.spacing[48],
    },
    ...inputVariants,
  };
};

export const InputAdornment: StyleFn = (theme, mode) => {
  const { color, size } = theme;

  return {
    root: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      position: "absolute",
      zIndex: 1,
      padding: `0px ${size.spacing[8]}`,
      color: color.text.neutral.moderate[mode],
      top: 0,
      left: "auto",
      right: 0,
      height: "100%",
    },
    _start: {
      left: 0,
      right: "auto",
      fontSize: size.spacing[20],
      "& svg": {
        width: size.spacing[20],
        height: size.spacing[20],
        fill: "currentColor",
      },
    },
    _end: {
      "& svg": {
        fill: "currentColor",
      },
    },
    _large: {
      "&$_start": {
        fontSize: size.spacing[24],
        "& svg": {
          width: size.spacing[24],
          height: size.spacing[24],
        },
      },
    },
    _xlarge: {
      "&$_start": {
        fontSize: size.spacing[24],
        "& svg": {
          width: size.spacing[24],
          height: size.spacing[24],
        },
      },
    },
    _small: {
      "&$_start": {
        fontSize: size.spacing[16],
        "& svg": {
          width: size.spacing[16],
          height: size.spacing[16],
        },
      },
    },
    _xsmall: {
      "&$_start": {
        fontSize: size.spacing[16],
        "& svg": {
          width: size.spacing[16],
          height: size.spacing[16],
        },
      },
    },
  };
};
